    @Transactional
    public Cargo deleteACargo(Integer trackingId){
    // Activity: deleteACargo      
    // InitialNode: InitialNode1
    // CallOperationAction: Find cargo  
    Cargo targetCargo = cargoRepository.findByTrackingId(trackingId);
    
    //NEXT: Find cargo ->Check if cargo exists
    // ConditionalNode: Check if cargo exists
    if (targetCargo != null) {
        // ConditionalNode: Check if there is no events
        if (targetCargo.getHistory().getEvents().isEmpty()) {
            // CallOperationAction: Delete the target cargo 
            Cargo deletedCargo = cargoRepository.deleteByTrackingId(trackingId);
            
            //NEXT: Delete the target cargo->ActivityFinalNode3
            return deletedCargo;
        } 
        else {
              // RaiseExceptionAction: CargoIsHandled
              throw new CargoIsHandled();
          }
        
    } 
    else {
          // RaiseExceptionAction: CargoNotFound
          throw new CargoNotFound();
      }
    
   };
 
    @Transactional
    public Cargo routeACargo(List<SharedLocation> selectedItinerary, Integer trackingId){
    // Activity: routeACargo      
    // InitialNode: Init
    // CallOperationAction: Find Cargo 
    Cargo targetCargo = cargoRepository.findByTrackingId(trackingId);
    
    //NEXT: Find Cargo->Cargo exists
    // ConditionalNode: Cargo exists
    if (targetCargo != null) {
        // ConditionalNode: Cargo is unrouted
        if (targetCargo.getItinerary().isEmpty()) {
            // ConditionalNode: Match with specification
            if (selectedItinerary.get(0).equals(targetCargo.getGoal().getDelivery().getSource()) && selectedItinerary.getLast().equals(targetCargo.getGoal().getDelivery().getDestination())) {
                // Assignment: Assign itinerary
                targetCargo.setItinerary(selectedItinerary);
                
                // ConditionalNode: Check current status
                if (targetCargo.getStatus().equals(TransportStatus.Received)) {
                    // Assignment: Mark as READY
                    targetCargo.setStatus(TransportStatus.Ready);
                    
                } 
                
                // CallOperationAction: Update Cargo Itinerary 
                Cargo updatedCargo = cargoRepository.save(targetCargo);
                
                //NEXT: Update Cargo Itinerary->ActivityFinalNode5
                return updatedCargo;
            } 
            else {
                  // RaiseExceptionAction: RouteMismatch
                  throw new RouteMismatch();
              }
            
        } 
        else {
              // RaiseExceptionAction: CargoAlreadyRouted
              throw new CargoAlreadyRouted();
          }
        
    } 
    else {
          // RaiseExceptionAction: CargoNotFound
          throw new CargoNotFound();
      }
    
   };
 
    @Transactional
    public void validateLocation(SharedLocation location){
    // Activity: validateLocation      
    // InitialNode: InitialNode1
    // CallOperationAction: checkLocation 
    Boolean locationFound = locationOutboundAdapter.checkLocation(location.getPortCode());
    
    //NEXT: checkLocation->Validate source
    // ConditionalNode: Validate source
    if (!(locationFound)) {
        // RaiseExceptionAction: LocationNotFound
        throw new LocationNotFound();
    } 
    
    return ;
   };
 
    @Transactional
    public List<Itinerary> requestRouteCandidates(Integer trackingId){
    // Activity: requestRouteCandidates      
    // InitialNode: Init
    // CallOperationAction: Find Cargo 
    Cargo targetCargo = cargoRepository.findByTrackingId(trackingId);
    
    //NEXT: Find Cargo->Cargo exists
    // ConditionalNode: Cargo exists
    if (targetCargo != null) {
        // CallOperationAction: getRouteCandidates 
        List<Itinerary> candidates = routePlanningOutboundAdapter.getRouteCandidates(targetCargo.getGoal().getDelivery().getDestination(), targetCargo.getGoal().getDelivery().getSource());
        
        //NEXT: getRouteCandidates->Done
        return candidates;
    } 
    else {
          // RaiseExceptionAction: CargoNotFound
          throw new CargoNotFound();
      }
    
   };
 
    @Transactional
    public void validateCarrierMovement(CarrierMovement carrierMovement){
    // Activity: validateCarrierMovement      
    // InitialNode: InitialNode1
    // CallOperationAction: Validate source 
    this.validateLocation(carrierMovement.getSource());
    
    //NEXT: Validate source->Validate destination
    // CallOperationAction: Validate destination 
    this.validateLocation(carrierMovement.getDestination());
    
    //NEXT: Validate destination->ActivityFinalNode6
    return ;
   };
 
    @Transactional
    public Cargo bookACargo(Integer customerId, Integer deadline, Integer destPort, Integer srcPort){
    // Activity: bookACargo      
    // InitialNode: Init
    // Declaration: Declare a cargo 
    Cargo newCargo = new Cargo();
    // CallOperationAction: checkCustomerExists 
    Boolean customerFound = customerOutboundAdapter.checkCustomerExists(customerId);
    
    //NEXT: checkCustomerExists->Validate customer
    // ConditionalNode: Validate customer
    if (customerFound) {
        // Assignment: Assign Customer
        if (newCargo.getRole() == null) {
            newCargo.setRole(new SharedCustomer());
        }
        if (newCargo.getRole() == null) {
            newCargo.setRole(new SharedCustomer());
        }
        newCargo.getRole().setCustomerId(customerId);
        
    } 
    else {
          // RaiseExceptionAction: CustomerNotFound
          throw new CustomerNotFound();
      }
    
    // Declaration: Declare delivery 
    CarrierMovement delivery = new CarrierMovement();
    // Assignment: Assign source
    if (delivery.getSource() == null) {
        delivery.setSource(new SharedLocation());
    }
    if (delivery.getSource() == null) {
        delivery.setSource(new SharedLocation());
    }
    delivery.getSource().setPortCode(srcPort);
    
    // Assignment: Assign Source
    if (delivery.getDestination() == null) {
        delivery.setDestination(new SharedLocation());
    }
    if (delivery.getDestination() == null) {
        delivery.setDestination(new SharedLocation());
    }
    delivery.getDestination().setPortCode(destPort);
    
    // CallOperationAction: Validate delivery 
    this.validateCarrierMovement(delivery);
    
    //NEXT: Validate delivery->Assign delivery
    // Assignment: Assign delivery
    if (newCargo.getGoal() == null) {
        newCargo.setGoal(new DeliverySpecification());
    }
    if (newCargo.getGoal() == null) {
        newCargo.setGoal(new DeliverySpecification());
    }
    newCargo.getGoal().setDelivery(delivery);
    
    // Assignment: Assign Deadline
    if (newCargo.getGoal() == null) {
        newCargo.setGoal(new DeliverySpecification());
    }
    if (newCargo.getGoal() == null) {
        newCargo.setGoal(new DeliverySpecification());
    }
    newCargo.getGoal().setDeadline(deadline);
    
    // Assignment: Assign status
    newCargo.setStatus(TransportStatus.Unreceived);
    
    // Declaration: Declare history 
    DeliveryHistory history = new DeliveryHistory();
    // Assignment: Assign history
    newCargo.setHistory(history);
    
    // CallOperationAction: Persist Booked Cargo 
    Cargo bookedCargo = cargoRepository.save(newCargo);
    
    //NEXT: Persist Booked Cargo->Final
    return bookedCargo;
   };
 
    @Transactional
    public TrackingReceipt trackACargo(Integer trackingId){
    // Activity: trackACargo      
    // InitialNode: Init
    // CallOperationAction: Lookup Cargo 
    Cargo targetCargo = cargoRepository.findByTrackingId(trackingId);
    
    //NEXT: Lookup Cargo->Cargo Exists
    // ConditionalNode: Cargo Exists
    if (targetCargo != null) {
        // CallOperationAction: Create tracking receipt 
        TrackingReceipt trackingReceipt = new TrackingReceipt(targetCargo.getHistory().getEvents(), targetCargo.getStatus(), targetCargo.getTrackingId());
         
        
        //NEXT: Create tracking receipt->Check last valid event
        // ConditionalNode: Check last valid event
        if (targetCargo.getHistory().getLastValidEvent() != null) {
            // Assignment: Assign port
            trackingReceipt.setLastLocation(targetCargo.getHistory().getLastValidEvent().getPort());
            
        } 
        else {
          }
        
        return trackingReceipt;
    } 
    else {
          // RaiseExceptionAction: CargoNotFound
          throw new CargoNotFound();
      }
    
   };
 
    @Transactional
    public HandlingEvent reportHandlingEvent(CarrierMovement carrierMovement, HandlingEventType eventType, SharedLocation port, Integer reportedTime, Integer trackingId){
    // Activity: reportHandlingEvent      
    // InitialNode: Init
    // CallOperationAction: Find cargo 
    Cargo targetCargo = cargoRepository.findByTrackingId(trackingId);
    
    //NEXT: Find cargo->Validate Cargo
    // ConditionalNode: Validate Cargo
    if (targetCargo != null) {
        // ConditionalNode: Check Leg
        if (carrierMovement != null) {
            // CallOperationAction: Validate carrier movement 
            this.validateCarrierMovement(carrierMovement);
            
            //NEXT: Validate carrier movement->FlowFinalNode4
        } 
        
        // ConditionalNode: Check Port
        if (port != null) {
            // CallOperationAction: Validate port 
            this.validateLocation(port);
            
            //NEXT: Validate port->FlowFinalNode4
        } 
        
        // CallOperationAction: Declare HandlingEvent 
        HandlingEvent newHandlingEvent = new HandlingEvent(carrierMovement, port, reportedTime, eventType);
         
        
        //NEXT: Declare HandlingEvent->Add handling event
        // Assignment: Add handling event
        if (targetCargo.getHistory() == null) {
            targetCargo.setHistory(new DeliveryHistory());
        }
        if (targetCargo.getHistory() == null) {
            targetCargo.setHistory(new DeliveryHistory());
        }
        targetCargo.getHistory().getEvents().add(newHandlingEvent);
        
        // CallOperationAction: Assign status 
         targetCargo.setStatusByEvent(newHandlingEvent);
         
        
        //NEXT: Assign status->Track last valid handling event
        // ConditionalNode: Track last valid handling event
        if (!targetCargo.getStatus().equals(TransportStatus.Mishandled)) {
            // Assignment: Assign last valid event
            if (targetCargo.getHistory() == null) {
                targetCargo.setHistory(new DeliveryHistory());
            }
            if (targetCargo.getHistory() == null) {
                targetCargo.setHistory(new DeliveryHistory());
            }
            targetCargo.getHistory().setLastValidEvent(newHandlingEvent);
            
        } 
        
        // CallOperationAction: Update Cargo 
        cargoRepository.save(targetCargo);
        
        //NEXT: Update Cargo->ActivityFinalNode12
        return newHandlingEvent;
    } 
    else {
          // RaiseExceptionAction: CargoNotFound
          throw new CargoNotFound();
      }
    
   };
 
